  },
];

const HIGHLIGHTED = [0, 4, 6]; // which thumbnails get highlighted

// ---- Thumbnail card ---------------------------------------------------------

const Thumbnail: React.FC<{
  thumb: Thumb;
  index: number;
  highlighted: boolean;
  highlightProgress: number;
  enterDelay: number;
}> = ({ thumb, index, highlighted, highlightProgress, enterDelay }) => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const enter = springIn(frame, vfps, enterDelay, "LIQUID");
  const ty = interpolate(enter, [0, 1], [40, 0]);
  const sc = interpolate(enter, [0, 1], [0.92, 1]);
  const bl = interpolate(enter, [0, 1], [10, 0]);

  // Drift each card uniquely
  const driftY = ambientDrift(frame, 2, 110, `thumb-y-${index}`);
  const driftX = ambientDrift(frame, 1.5, 130, `thumb-x-${index}`);

  // Highlight pop — scale + lift + orange ring
  const hp = highlighted ? highlightProgress : 0;
  const highlightScale = 1 + hp * 0.04;
  const highlightLift = -hp * 8;
  const ringOpacity = hp;
  const ringWidth = 3 + hp * 1;

  // De-emphasize non-highlighted when highlights are active
  const anyHighlighted = highlightProgress > 0.01;
  const dim = anyHighlighted && !highlighted ? 1 - highlightProgress * 0.35 : 1;
  const dimScale = anyHighlighted && !highlighted ? 1 - highlightProgress * 0.02 : 1;

  return (
    <div
      style={{
        position: "relative",
        opacity: enter * dim,
        transform: `translate(${driftX}px, ${driftY + ty + highlightLift}px) scale(${sc * highlightScale * dimScale})`,
        filter: `blur(${bl}px)`,
        transformOrigin: "center center",
      }}
    >
      {/* Orange highlight ring */}
      <div
        style={{
          position: "absolute",
          inset: -ringWidth - 6,
          borderRadius: 22,
          border: `${ringWidth}px solid ${COLORS.orange}`,
          opacity: ringOpacity,
          pointerEvents: "none",
          boxShadow: `0 0 ${40 * hp}px ${COLORS.orangeDeep}55`,
        }}
      />

      {/* Card */}
      <div
        style={{
          backgroundColor: COLORS.card,
          border: `1px solid ${COLORS.border}`,
          borderRadius: 18,
          overflow: "hidden",
          width: "100%",
          fontFamily: BRAND.fonts.marketing,
          boxShadow: "0 18px 48px rgba(0,0,0,0.55)",
        }}
      >
        {/* Thumbnail image area */}
        <div
          style={{
            position: "relative",
            width: "100%",
            aspectRatio: "16 / 9",
            background: `linear-gradient(135deg, ${thumb.hueA}, ${thumb.hueB})`,
            overflow: "hidden",
          }}
        >
          {/* Faux content shapes */}
          <div
            style={{
              position: "absolute",
              left: "8%",
              top: "18%",
              width: "55%",
              height: 18,
              backgroundColor: "rgba(255,255,255,0.18)",
              borderRadius: 4,
            }}
          />
          <div
            style={{
              position: "absolute",
              left: "8%",
              top: "32%",
              width: "38%",
              height: 18,
              backgroundColor: "rgba(255,255,255,0.12)",
              borderRadius: 4,
            }}
          />
          {/* Big faux subject */}
          <div
            style={{
              position: "absolute",
              right: "-6%",
              bottom: "-15%",
              width: 220,
              height: 220,
              borderRadius: "50%",
              background: `radial-gradient(closest-side, ${COLORS.orange}33, transparent)`,
              filter: "blur(2px)",
            }}
          />
          <div
            style={{
              position: "absolute",
              left: "8%",
              bottom: "12%",
              fontFamily: BRAND.fonts.marketing,
              fontWeight: 600,
              fontSize: 38,
              color: COLORS.text,
              letterSpacing: "-0.02em",
              lineHeight: 1.05,
              maxWidth: "75%",
              textShadow: "0 2px 8px rgba(0,0,0,0.6)",
            }}
          >
            {thumb.title.length > 42
              ? thumb.title.slice(0, 40) + "…"
              : thumb.title}
          </div>

          {/* Duration pill */}
          <div
            style={{
              position: "absolute",
              right: 14,
              bottom: 14,
              backgroundColor: "#000",
              color: "#fff",
              fontFamily: BRAND.fonts.primary,
              fontWeight: 600,
              fontSize: 18,
              padding: "4px 8px",
              borderRadius: 4,
            }}
          >
            {thumb.duration}
          </div>

          {/* Optional badge */}
          {thumb.badge && (
            <div
              style={{
                position: "absolute",
                left: 14,
                top: 14,
                backgroundColor: COLORS.card,
                border: `1.5px solid ${COLORS.orange}`,
                color: COLORS.orange,
                fontFamily: BRAND.fonts.marketing,
                fontWeight: 600,
                fontSize: 16,
                padding: "4px 10px",
                borderRadius: 6,
                letterSpacing: "0.08em",
              }}
            >
              {thumb.badge}
            </div>
          )}
        </div>

        {/* Meta row */}
        <div
          style={{
            padding: "18px 20px 20px",
            display: "flex",
            gap: 14,
            alignItems: "flex-start",
          }}
        >
          {/* Avatar */}
          <div
            style={{
              width: 44,
              height: 44,
              borderRadius: "50%",
              backgroundColor: COLORS.border,
              flexShrink: 0,
              background: `linear-gradient(135deg, ${thumb.hueA}, ${COLORS.orange})`,
            }}
          />
          <div style={{ flex: 1, minWidth: 0 }}>
            <div
              style={{
                fontFamily: BRAND.fonts.marketing,
                fontWeight: 600,
                fontSize: 22,
                color: COLORS.text,
                lineHeight: 1.25,
                letterSpacing: "-0.01em",
                marginBottom: 8,
                display: "-webkit-box",
                WebkitLineClamp: 2,
                WebkitBoxOrient: "vertical",
                overflow: "hidden",
              }}
            >
              {thumb.title}
            </div>
            <div
              style={{
                fontFamily: BRAND.fonts.primary,
                fontSize: 18,
                color: COLORS.textMuted,
                marginBottom: 2,
              }}
            >
              {thumb.channel}
            </div>
            <div
              style={{
                fontFamily: BRAND.fonts.primary,
                fontSize: 17,
                color: COLORS.textSubtle,
              }}
            >
              {thumb.views} · {thumb.age}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

// ---- Main scene -------------------------------------------------------------

const SCENE_DUR = 260;

const ThumbnailGridScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const eyebrowIn = springIn(frame, vfps, 4, "SNAPPY");
  const titleIn = springIn(frame, vfps, 10, "SNAPPY");
  const highlightPillIn = springIn(frame, vfps, 22, "LIQUID");

  // Highlight ramp — comes in after the grid lands
  const highlightProgress = spring({
    frame: frame - 110,
    fps: vfps,
    config: SPRINGS.LIQUID,
  });

  // Headline drift
  const headDrift = ambientDrift(frame, 2, 130, "headline");

  return (
    <AbsoluteFill style={{ fontFamily: BRAND.fonts.marketing }}>
      {/* Header block — top, asymmetric left */}
      <div
        style={{
          position: "absolute",
          left: "5%",
          top: "5%",
          right: "5%",
          display: "flex",
          flexDirection: "column",
          gap: 18,
          transform: `translateY(${headDrift}px)`,
        }}
      >
        <div
          style={{
            fontFamily: BRAND.fonts.primary,
            fontSize: 38,
            color: COLORS.textMuted,
            letterSpacing: "0.06em",
            textTransform: "uppercase",
            fontWeight: 500,
            opacity: eyebrowIn,
            transform: `translateY(${interpolate(eyebrowIn, [0, 1], [16, 0])}px)`,
          }}
        >
          Scraping YouTube at scale
        </div>

        <div
          style={{
            fontFamily: BRAND.fonts.marketing,
            fontWeight: 600,
            fontSize: 120,
            color: COLORS.text,
            letterSpacing: "-0.03em",
            lineHeight: 1.02,
            maxWidth: "75%",
            opacity: titleIn,
            transform: `translateY(${interpolate(titleIn, [0, 1], [28, 0])}px)`,
          }}
        >
          Find the{" "}
          <span
            style={{
              backgroundColor: COLORS.card,
              borderBottom: `4px solid ${COLORS.orange}`,
              padding: "0 16px",
              borderRadius: 10,
              color: COLORS.text,
              clipPath: `inset(0 ${interpolate(highlightPillIn, [0, 1], [100, 0])}% 0 0)`,
            }}
          >
            top-performing videos
          </span>{" "}
          in your niche
        </div>
      </div>

      {/* 3x3 thumbnail grid */}
      <div
        style={{
          position: "absolute",
          left: "5%",
          right: "5%",
          top: "32%",
          display: "grid",
          gridTemplateColumns: "repeat(3, 1fr)",
          gridTemplateRows: "repeat(3, 1fr)",
          gap: 48,
          height: "62%",
        }}
      >
        {THUMBS.map((thumb, i) => (
          <Thumbnail
            key={i}
            thumb={thumb}
            index={i}
            highlighted={HIGHLIGHTED.includes(i)}
            highlightProgress={highlightProgress}
            enterDelay={32 + i * 6}
          />
        ))}
      </div>
    </AbsoluteFill>
  );
};

// ---- Scene wrapper for exit animation ---------------------------------------

const SceneWrap: React.FC<{ dur: number; children: React.ReactNode }> = ({
  dur,
  children,
}) => {
  const frame = useCurrentFrame();
  return <AbsoluteFill style={sceneExit(frame, dur)}>{children}</AbsoluteFill>;
};

// ---- Main composition -------------------------------------------------------

export const durationInFrames = SCENE_DUR;

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={SCENE_DUR}>
        <ThumbnailGridScene />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
